const body    = $input.first().json.body;
const action  = body.action  || '';
const payload = body.payload || {};

const _id       = payload._id             || '';
const type      = payload.type            || '';
const reservaId = payload.id              || '';
const idclient  = payload._idclient       || '';
const guests    = payload.guests          || 0;
const price     = payload.price?._f_total || '';
const canal     = payload.partner?.name   || '';
const codCanal  = payload.partnerCode     || '';
const now       = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// FIX: se houver unidade filho, priorizar dados dela
const child     = (payload.childs && payload.childs.length > 0) ? payload.childs[0] : null;
const idlisting = child?._idlisting   || payload._idlisting   || '';
const checkIn   = child?.checkInDate  || payload.checkInDate  || payload.from || '';
const checkOut  = child?.checkOutDate || payload.checkOutDate || payload.to   || '';

const lista       = payload.guestsDetails?.list || [];
const primary     = lista.find(g => g.primary) || lista[0] || {};
const hospedeName = primary.name             || '';
const hospedeFone = primary.phones?.[0]?.iso || '';

// newStatus deriva do estado atual da reserva (payload.type).
// Exceção: reservation.deleted não carrega type no payload, então mapeia pelo action.
// Qualquer type fora do esperado retorna '' — sem fallback silencioso.
const typeStatusMap = {
  'booked': 'reservado',
  'reserved': 'pre',
  'blocked':  'bloqueado',
  'canceled': 'cancelada',
};
const newStatus = action === 'reservation.deleted'
  ? 'deletada'
  : (typeStatusMap[type] || '');

return [{ 
  json: {
    _id, action, type, reservaId, idlisting,
    checkIn, checkOut, guests, price, idclient,
    canal, codCanal, hospedeName, hospedeFone, newStatus, now
  } 
}];

const parsed  = $('Code: Parse Payload').first().json;
const unidade = $input.first().json;

const unidadeNome = unidade.unidade_nome || parsed.idlisting;
const equipeId    = unidade.equipe_id    || '';
const horaLimpeza = unidade.hora_limpeza || '';

return [{ json: {
  reserva_id:            parsed.reservaId,
  unidade_nome:          unidadeNome,
  data_checkin:          parsed.checkIn,
  data_checkout:         parsed.checkOut,
  atencao:               '',
  hora_limpeza_agendada: horaLimpeza,
  equipe_id:             equipeId,
  status:                parsed.newStatus,
  hospede_nome:          parsed.hospedeName,
  hospede_id:            parsed.hospedeFone,
  hospede_qtd:           parsed.guests,
  cod_canal:             parsed.codCanal,
  canal:                 parsed.canal,
  valor_total:           parsed.price,
  hora_checkin:          unidade.hora_checkin  || '',
  hora_checkout:         unidade.hora_checkout || '',
  criado_em:             parsed.now,
  ultima_atualizacao:    parsed.now,
  _id:                   parsed._id
} }];

