// =============================================================
// Avalia se a alteração deve disparar o alerta em tempo real pro prestador
// Critérios: data antiga era hoje (SP), data nova !== hoje (SP),
//            hora SP estritamente entre 07:00 e 16:00
// =============================================================

var logAntigo = $('Sheets: Buscar LOG Antigo').item.json;
var parsed    = $('Code: Parse Payload').item.json;

function nowSP() {
  var s = new Date().toLocaleString('en-US', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false
  });
  var m = s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4}),?\s+(\d{1,2}):(\d{2}):(\d{2})/);
  if (!m) return new Date();
  return new Date(parseInt(m[3]), parseInt(m[1]) - 1, parseInt(m[2]),
                  parseInt(m[4]), parseInt(m[5]), parseInt(m[6]));
}

function pad2(n) { return n < 10 ? '0' + n : '' + n; }
function isoLocal(d) {
  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
}
function norm(d) { return String(d || '').slice(0, 10); }

var agoraSP = nowSP();
var hojeStr = isoLocal(new Date(agoraSP.getFullYear(), agoraSP.getMonth(), agoraSP.getDate()));

var dataAntiga = norm(logAntigo.data_checkout);
var dataNova   = norm(parsed.checkOut);

var horaSP     = agoraSP.getHours() * 60 + agoraSP.getMinutes();
var dentroJanela = horaSP >= (7 * 60) && horaSP < (16 * 60);

var disparar = (dataAntiga === hojeStr)
            && (dataNova !== hojeStr)
            && dentroJanela;

return [{
  json: {
    disparar_alerta_realtime: disparar,
    equipe_id:     String(logAntigo.equipe_id || '').trim()
  }
}];

